using System.IO.Compression;

namespace ArcZipWindows;

public sealed class ZipArchiveService
{
 public IReadOnlyList<ArchiveEntryRow> List(string archivePath) { using var archive=ZipFile.OpenRead(archivePath); return archive.Entries.Select(e=>new ArchiveEntryRow { Name=e.FullName, Kind=e.FullName.EndsWith('/')?"Folder":"File", Length=e.Length, Modified=e.LastWriteTime }).OrderBy(e=>e.Kind=="Folder"?0:1).ThenBy(e=>e.Name,StringComparer.OrdinalIgnoreCase).ToList(); }
 public void Create(string destination,IEnumerable<string> files) { using var archive=ZipFile.Open(destination,ZipArchiveMode.Create); foreach(var file in files){var info=new FileInfo(file);var entry=archive.CreateEntry(info.Name,CompressionLevel.Optimal);entry.LastWriteTime=new DateTimeOffset(info.LastWriteTime);using var input=File.OpenRead(file);using var output=entry.Open();input.CopyTo(output);} }
 public void AddFiles(string archivePath,IEnumerable<string> files) { Rewrite(archivePath,entry=>entry.FullName,files.Select(Path.GetFullPath).ToList()); }
 public void DeleteEntries(string archivePath,IEnumerable<string> names) { var remove=names.ToHashSet(StringComparer.Ordinal); Rewrite(archivePath,entry=>remove.Contains(entry.FullName)?null:entry.FullName,[]); }
 public void RenameEntry(string archivePath,string oldName,string newName) { if(string.IsNullOrWhiteSpace(newName)||newName.StartsWith('/')||newName.Split('/').Any(p=>p=="..")||newName.Contains('\\')) throw new ArgumentException("Enter a safe archive-relative name."); Rewrite(archivePath,entry=>entry.FullName==oldName?newName:entry.FullName,[]); }
 private static void Rewrite(string archivePath,Func<ZipArchiveEntry,string?> map,IReadOnlyList<string> additions) { var fullPath=Path.GetFullPath(archivePath);var tempPath=fullPath+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var source=ZipFile.OpenRead(fullPath))using(var destination=ZipFile.Open(tempPath,ZipArchiveMode.Create)){foreach(var entry in source.Entries){var name=map(entry);if(name is null)continue;var target=destination.CreateEntry(name,CompressionLevel.Optimal);if(entry.LastWriteTime.Year>=1980&&entry.LastWriteTime.Year<=2107)target.LastWriteTime=entry.LastWriteTime;using var input=entry.Open();using var output=target.Open();input.CopyTo(output);}foreach(var file in additions){var info=new FileInfo(file);var target=destination.CreateEntry(info.Name,CompressionLevel.Optimal);using var input=File.OpenRead(file);using var output=target.Open();input.CopyTo(output);}}File.Move(tempPath,fullPath,true);}finally{if(File.Exists(tempPath))File.Delete(tempPath);} }
 public void ExtractEntries(string archivePath,IEnumerable<string> names,string outputDirectory) { var selected=names.ToHashSet(StringComparer.Ordinal);var root=Path.GetFullPath(outputDirectory);Directory.CreateDirectory(root);using var archive=ZipFile.OpenRead(archivePath);foreach(var entry in archive.Entries.Where(e=>selected.Contains(e.FullName))){var target=Path.GetFullPath(Path.Combine(root,entry.FullName.Replace('/',Path.DirectorySeparatorChar)));var prefix=root.EndsWith(Path.DirectorySeparatorChar)?root:root+Path.DirectorySeparatorChar;if(!target.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)&&!string.Equals(target,root,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException($"Unsafe archive path rejected: {entry.FullName}");if(entry.FullName.EndsWith('/')){Directory.CreateDirectory(target);continue;}Directory.CreateDirectory(Path.GetDirectoryName(target)!);entry.ExtractToFile(target,overwrite:true);} }
}
